"""Pseudo-ECG integrands of the manufactured monodomain fields on the unit cube and their Gauss-Legendre reference; integrand_<case>(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz).  Generated by pseudo_ecg_mms.py."""

import numpy

# module: pseudo_ecg

PARAMS = {'SIGMA_FDA': [0.111453302, 0.12158542, 0.030396355], 'SIGMA_ROTATED': [0.106875, -0.0084931, -0.022561, 0.116682, -0.0130256, 0.0398782], 'QUADRATURE_ORDER': 96, 'VSMALL': 1e-300}


def integrand_d1(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz):
    _ref = numpy.zeros(numpy.broadcast(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz).shape)
    _t0 = ex - x
    _t1 = abs(_t0)
    return (numpy.select([numpy.less_equal(_t1, 1.0e-300),True], [0,numpy.pi*sxx*numpy.sin(numpy.pi*x)/(_t0*_t1)], default=numpy.nan)) + _ref


def integrand_d2(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz):
    _ref = numpy.zeros(numpy.broadcast(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz).shape)
    _t0 = -ex + x
    _t1 = -ey + y
    _t2 = _t0**2 + _t1**2
    _t3 = 2*numpy.pi
    _t4 = _t3*y
    _t5 = numpy.pi*x
    _t6 = numpy.pi*numpy.sin(_t5)*numpy.cos(_t4)
    _t7 = _t3*numpy.sin(_t4)*numpy.cos(_t5)
    return (numpy.select([numpy.less_equal(_t2, 1.0e-300),True], [0,(_t0*(-_t6*sxx - _t7*sxy) + _t1*(-_t6*sxy - _t7*syy))/_t2**(3/2)], default=numpy.nan)) + _ref


def integrand_d3(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz):
    _ref = numpy.zeros(numpy.broadcast(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz).shape)
    _t0 = -ex + x
    _t1 = -ey + y
    _t2 = -ez + z
    _t3 = _t0**2 + _t1**2 + _t2**2
    _t4 = 2*numpy.pi
    _t5 = _t4*y
    _t6 = numpy.cos(_t5)
    _t7 = 3*numpy.pi
    _t8 = _t7*z
    _t9 = numpy.cos(_t8)
    _t10 = numpy.pi*x
    _t11 = numpy.pi*_t6*_t9*numpy.sin(_t10)
    _t12 = numpy.cos(_t10)
    _t13 = _t12*_t4*_t9*numpy.sin(_t5)
    _t14 = _t12*_t6*_t7*numpy.sin(_t8)
    return (numpy.select([numpy.less_equal(_t3, 1.0e-300),True], [0,(_t0*(-_t11*sxx - _t13*sxy - _t14*sxz) + _t1*(-_t11*sxy - _t13*syy - _t14*syz) + _t2*(-_t11*sxz - _t13*syz - _t14*szz))/_t3**(3/2)], default=numpy.nan)) + _ref


def integrand_rotated(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz):
    _ref = numpy.zeros(numpy.broadcast(x, y, z, ex, ey, ez, sxx, sxy, sxz, syy, syz, szz).shape)
    _t0 = -ex + x
    _t1 = -ey + y
    _t2 = -ez + z
    _t3 = _t0**2 + _t1**2 + _t2**2
    _t4 = numpy.pi*y
    _t5 = numpy.sin(_t4)
    _t6 = _t5**2
    _t7 = numpy.pi*x
    _t8 = numpy.sin(_t7)
    _t9 = numpy.pi*z
    _t10 = numpy.sin(_t9)
    _t11 = 2*numpy.pi*_t10**2
    _t12 = _t11*_t6*_t8*numpy.cos(_t7)
    _t13 = _t8**2
    _t14 = _t11*_t13*_t5*numpy.cos(_t4)
    _t15 = 2*numpy.pi*_t10*_t13*_t6*numpy.cos(_t9)
    return (numpy.select([numpy.less_equal(_t3, 1.0e-300),True], [0,(_t0*(_t12*sxx + _t14*sxy + _t15*sxz) + _t1*(_t12*sxy + _t14*syy + _t15*syz) + _t2*(_t12*sxz + _t14*syz + _t15*szz))/_t3**(3/2)], default=numpy.nan)) + _ref


CASE_DIMENSION = {"d1": 1, "d2": 2, "d3": 3, "rotated": 3}


def _sigma_entries(sigma):
    s = numpy.asarray(sigma, dtype=float)
    if s.shape == (3, 3):
        return (s[0, 0], s[0, 1], s[0, 2], s[1, 1], s[1, 2], s[2, 2])
    return tuple(float(v) for v in s)


def time_factor(t):
    return numpy.sqrt(1.0 + t)


def spatial_reference(case, sigma, electrode, order):
    """Integral of the integrand over [0, 1]^d (d from case: d1, d2, d3,
    rotated) with `order` Gauss-Legendre points per axis.  sigma is a 3x3
    array or (xx, xy, xz, yy, yz, zz); electrode is (ex, ey, ez)."""
    d = CASE_DIMENSION[case]
    nodes, weights = numpy.polynomial.legendre.leggauss(order)
    nodes = 0.5*(nodes + 1.0)
    weights = 0.5*weights
    grid = numpy.meshgrid(*([nodes]*d), indexing="ij")
    w = numpy.ones_like(grid[0])
    for i in range(d):
        shape = [1]*d
        shape[i] = order
        w = w*weights.reshape(shape)
    coords = list(grid) + [numpy.zeros_like(grid[0])]*(3 - d)
    f = globals()["integrand_" + case]
    with numpy.errstate(divide="ignore", invalid="ignore"):
        values = f(*coords, *electrode, *_sigma_entries(sigma))
    return float(numpy.sum(w*values))


def reference(case, sigma, electrode, t, order):
    return time_factor(t)*spatial_reference(case, sigma, electrode, order)
